00047 template <typename A, typename B, size_t N> B piecewise_linear(const std::array<A, N> &a, const std::array<B, N> &b, A v) {
00048     CHECK(N > 0);
00049 
00050     // Check top and bottom of range
00051     if (v <= a[0])
00052         return b[0];
00053     if (v >= a[N - 1])
00054         return b[N - 1];
00055 
00056     // Find pair that input falls between
00057     unsigned i = 0;
00058     for (i = 0; i < N - 1; ++i)
00059         if (v < a[i + 1])
00060             break;
00061 
00062     // Lerp
00063     return int(v - a[i]) * (b[i + 1] - b[i]) / int(a[i + 1] - a[i]) + b[i];
00064 }
00065 
00066 static const std::array<unsigned, 4> step_widths = {800, 1250, 1900, 2250};
00067 
00068 static const std::array<int, 4> dequant_offset = {50, 50, 110, 110};
00069 static const std::array<int, 4> temporal_cq_sw_multiplier = {500, 500, 600, 700};
00070 static const std::array<int, 4> temporal_step_width_modifier = {48, 30, 20, 10};
00071 
00072 Parameters parameter_defaults_global(const Parameters &p) {
00073     auto pb = Parameters::build();
00074 
00075     ParameterConfig config = p["parameter_config"].get_enum<ParameterConfig>(ParameterConfig_Default);
00076     if (config == ParameterConfig_Default) {
00077         const unsigned step_width_2 = p["cq_step_width_loq_0"].get<unsigned>(32767);
00078         unsigned base_qp = p["qp"].get<unsigned>(28);
00079         unsigned planes = p["num_processed_planes"].get<unsigned>(1);
00080         const unsigned width = p["width"].get<unsigned>(1920);
00081         const unsigned height = p["height"].get<unsigned>(1080);
00082         const unsigned resolution = (10000 * width) + (height);
00083         BaseCoding base_codec = BaseCoding_AVC;
00084         if (lowercase(p["base_encoder"].get<std::string>()).compare("hevc") == 0 ||
00085             lowercase(p["base_encoder"].get<std::string>()).compare("baseyuv_hevc") == 0)
00086             base_codec = BaseCoding_HEVC;
00087         else if (lowercase(p["base_encoder"].get<std::string>()).compare("vvc") == 0 ||
00088                  lowercase(p["base_encoder"].get<std::string>()).compare("baseyuv_vvc") == 0)
00089             base_codec = BaseCoding_VVC;
00090         else if (lowercase(p["base_encoder"].get<std::string>()).compare("evc") == 0 ||
00091                  lowercase(p["base_encoder"].get<std::string>()).compare("baseyuv_evc") == 0)
00092             base_codec = BaseCoding_EVC;
00093         else if (lowercase(p["base_encoder"].get<std::string>()).compare("x265") == 0 ||
00094                  lowercase(p["base_encoder"].get<std::string>()).compare("baseyuv_x265") == 0)
00095             base_codec = BaseCoding_EVC;
00096 
00097         // Base qp
00098         if (p["qp"].empty()) {
00099             if (base_codec == BaseCoding_AVC) {
00100                 if ((resolution <= ((10000 * 1920) + (1080))))
00101                     base_qp = (int)((0.007f * (float)(step_width_2)) + 4.85f);
00102                 else
00103                     base_qp = (int)((0.018079f * (float)(step_width_2)) - 33.71f);
00104             } else if (base_codec == BaseCoding_HEVC) {
00105                 if ((resolution <= ((10000 * 1920) + (1080))))
00106                     base_qp = (int)((0.012f * (float)(step_width_2)) - 15.5f);
00107                 else
00108                     base_qp = (int)((0.0148f * (float)(step_width_2)) - 21.751f);
00109             } else if (base_codec == BaseCoding_EVC) {
00110                 if ((resolution <= ((10000 * 1920) + (1080))))
00111                     base_qp = (int)((0.0068f * (float)(step_width_2)) + 3.9939f);
00112                 else
00113                     base_qp = (int)((0.0131f * (float)(step_width_2)) - 16.669f);
00114             } else if (base_codec == BaseCoding_VVC) {
00115                 if ((resolution <= ((10000 * 1920) + (1080))))
00116                     base_qp = (int)((0.012f * (float)(step_width_2)) - 15.5f);
00117                 else
00118                     base_qp = (int)((0.0148f * (float)(step_width_2)) - 22.07f);
00119             }
00120             base_qp = clamp(base_qp, (unsigned)MIN_BASE_QP, (unsigned)MAX_BASE_QP);
00121         }
00122         pb.set("qp", (unsigned)base_qp);
00123 
00124         // YUV mode (chroma planes)
00125         if (base_qp >= 27) {
00126             planes = 1;
00127             pb.set("num_processed_planes", (unsigned)1); // Y only
00128         } else {
00129             // (base_qp <= 26)
00130             planes = 3;
00131             pb.set("num_processed_planes", (unsigned)3); // YUV
00132         }
00133 
00134         REPORT("QP                              %8d", base_qp);
00135         REPORT("width                           %8d", width);
00136         REPORT("height                          %8d", height);
00137         REPORT("num_processed_planes            %8d", planes);
00138     }
00139 
00140     else if (config == ParameterConfig_Conformance) {
00141         REPORT("Using Conformance Parameters");
00142         pb.set("encoding_upsample", std::string("modifiedcubic"));
00143         pb.set("encoding_transform_type", std::string("dds"));
00144         pb.set("num_processed_planes", (unsigned)1);
00145         pb.set("temporal_step_width_modifier", (unsigned)48);
00146         pb.set("qp", (unsigned)28);
00147     }
00148 
00149     return pb.finish();
00150 }
